export default function BrainMap() {
  const [activeZone, setActiveZone] = useState('about');
  const [darkMode, setDarkMode] = useState(true);

  useEffect(() => {
    document.body.style.backgroundColor = darkMode
      ? '#000000'
      : '#ffffff';

    document.body.style.color = darkMode
      ? '#ffffff'
      : '#000000';
  }, [darkMode]);

  const theme = darkMode
    ? {
        background: '#000000',
        text: '#ffffff',
        muted: '#a3a3a3',
        card: '#0a0a0a',
        border: '#262626',
        accent: '#ffffff',
      }
    : {
        background: '#ffffff',
        text: '#000000',
        muted: '#525252',
        card: '#ffffff',
        border: '#e5e5e5',
        accent: '#000000',
      };

  const activeContent = CONTENT[activeZone];

  return (
    <main
      className="min-h-screen w-full transition-colors duration-300"
      style={{
        backgroundColor: theme.background,
        color: theme.text,
      }}
    >
      {/* Theme Toggle */}
      <button
        onClick={() => setDarkMode((prev) => !prev)}
        aria-label="Toggle color theme"
        className="fixed top-5 right-5 z-50 w-10 h-10 rounded-full border flex items-center justify-center transition-all duration-200 hover:scale-110"
        style={{
          borderColor: theme.border,
          backgroundColor: theme.card,
          color: theme.text
        }}
      >
        {darkMode ? '☀' : '☾'}
      </button>

      <div className="w-full max-w-6xl mx-auto px-4 sm:px-6 py-8 sm:py-10">

        <div className="flex flex-col items-center text-center mb-12 sm:mb-16">

          {/* Profile Photo with Accent Glow */}
          <div 
            className="w-32 h-32 sm:w-40 sm:h-40 rounded-full overflow-hidden border-4 mb-6 shadow-xl transition-transform duration-300 hover:scale-105"
            style={{ 
              borderColor: theme.accent,
              boxShadow: `0 0 25px ${theme.accent}40` 
            }}
          >
            <img 
              src={profilePic} 
              alt="Gavin Austin" 
              className="w-full h-full object-cover"
            />
          </div>

          {/* Name */}
          <h1 className="text-4xl sm:text-5xl font-extrabold tracking-tight mb-2">
            Gavin Austin
          </h1>

          {/* Professional Title */}
          <p 
            className="text-base sm:text-lg font-medium font-mono mb-8" 
            style={{ color: theme.accent }}
          >
            $&gt; I like to code &lt;$
          </p>

          {/* Social Links + High-Visibility Resume Button */}
          <div className="flex flex-wrap items-center justify-center gap-4">
            
            {SOCIALS.map((social) => (
              <a
                key={social.name}
                href={social.href}
                aria-label={social.name}
                target="_blank"
                rel="noopener noreferrer"
                className="w-11 h-11 rounded-full flex items-center justify-center transition-all duration-200 hover:-translate-y-1 hover:shadow-lg"
                style={{
                  backgroundColor: theme.card,
                  border: `1px solid ${theme.border}`,
                }}
              >
                <img
                  src={social.icon}
                  alt=""
                  className="w-5 h-5"
                  style={!darkMode ? { filter: 'invert(1)' } : {}}
                />
              </a>
            ))}

            {/* Resume CTA */}
            <a
              href={resumePdf}
              target="_blank"
              rel="noopener noreferrer"
              className="ml-2 inline-flex items-center gap-2 px-6 py-2.5 rounded-full font-bold transition-all duration-200 hover:-translate-y-1 hover:shadow-lg"
              style={{
                backgroundColor: theme.accent,
                color: theme.background,
              }}
            >
              <span>View Resume</span>
              {/* Clean External Link Icon */}
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"></path>
              </svg>
            </a>
            
          </div>
        </div>

        <div className="flex flex-col md:flex-row items-center justify-center gap-8 sm:gap-12">

          {/* Brain */}
          <div className="relative w-[220px] sm:w-[280px] md:w-[360px] lg:w-[400px] shrink-0">

            <svg
              xmlns="http://www.w3.org/2000/svg"
              viewBox="0 0 400 480"
              className="w-full h-auto drop-shadow-xl"
            >
              {LOBES.map((lobe) => (
                <g
                  key={lobe.id}
                  transform={lobe.transform}
                  onClick={() => setActiveZone(lobe.id)}
                  className="cursor-pointer"
                >
                  <path
                    d={lobe.d}
                    className="transition-all duration-300 hover:scale-105"
                    style={{ transformOrigin: 'center', transformBox: 'fill-box' }}
                    fill={
                      activeZone === lobe.id
                        ? theme.accent
                        : darkMode
                        ? '#171717'
                        : '#f5f5f5'
                    }
                    stroke={
                      activeZone === lobe.id
                        ? theme.accent
                        : darkMode
                        ? '#404040'
                        : '#d4d4d4'
                    }
                    strokeWidth="2"
                  />
                </g>
              ))}
            </svg>

          </div>

          {/* Content Card */}
          <div
            className="w-full md:w-[400px] min-h-[280px] rounded-2xl border p-6 sm:p-8 shadow-sm transition-all duration-300"
            style={{
              backgroundColor: theme.card,
              borderColor: theme.border,
            }}
          >
            <h2
              className="text-2xl sm:text-3xl font-bold mb-5"
              style={{ color: theme.accent }}
            >
              {activeContent.heading}
            </h2>

            <div
              className="text-sm sm:text-base leading-relaxed"
              style={{ color: theme.muted }}
            >
              {activeContent.body}
            </div>
          </div>

        </div>

        {/* Navigation Labels */}
        <div className="flex flex-wrap justify-center gap-3 mt-12">
          {LOBES.map((lobe) => (
            <button
              key={lobe.id}
              onClick={() => setActiveZone(lobe.id)}
              className="px-4 py-2 rounded-lg text-sm capitalize transition-all duration-200 font-medium"
              style={{
                backgroundColor:
                  activeZone === lobe.id
                    ? theme.accent
                    : theme.card,
                color:
                  activeZone === lobe.id
                    ? theme.background
                    : theme.muted,
                border: `1px solid ${
                  activeZone === lobe.id
                    ? theme.accent
                    : theme.border
                }`,
              }}
            >
              {lobe.id}
            </button>
          ))}
        </div>

      </div>
    </main>
  );
}